#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: secrets e configuração do bunzina-billing.
# ──────────────────────────────────────────────────────────────────────────

REPO="Bunzina/bunzina-billing"

run_wizard() {

cd "$(dirname "${BASH_SOURCE[0]}")/.."
export GH_REPO="$REPO"

require() {
  [[ -n "$2" ]] || { warn "$1 veio vazio. Rode o script de novo."; exit 1; }
}

stage_preflight() {
  stage "GitHub CLI"
  say "Os secrets são gravados em $REPO pelo gh."
  if ! command -v gh >/dev/null 2>&1; then
    warn "gh não encontrado. Instale em https://cli.github.com e rode de novo."
    exit 1
  fi
  if ! gh auth status >/dev/null 2>&1; then
    warn "gh não está autenticado. Rode 'gh auth login' e execute este script de novo."
    exit 1
  fi
  if ! gh repo view "$REPO" >/dev/null 2>&1; then
    warn "A conta atual do gh não enxerga $REPO."
    exit 1
  fi
  say "gh autenticado e $REPO acessível."
  pause
}

# Secrets que vivem na organização Bunzina e valem para todos os repositórios.
# O wizard nunca grava estes nomes no repositório: um secret do repositório com
# o mesmo nome sobrescreve o da org e deixa de acompanhar a renovação.
ORG_SECRETS=(AWS_ACCESS_KEY_ID AWS_SECRET_ACCESS_KEY AWS_SESSION_TOKEN AWS_ACCOUNT_ID DB_PASSWORD)
ORG_SECRETS_URL="https://github.com/organizations/Bunzina/settings/secrets/actions"

check_org_secrets() {
  local visible repo_level name
  local -a missing=() shadowing=()

  if ! visible=$(gh api "repos/$REPO/actions/organization-secrets" --paginate --jq '.secrets[].name' 2>/dev/null); then
    SKIPPED+=("conferir se os secrets da org chegam em $REPO (a API recusou a consulta)")
    warn "Não consegui consultar os secrets da org visíveis para $REPO."
    return
  fi
  repo_level=$(gh secret list --json name --jq '.[].name' 2>/dev/null || true)

  for name in "${ORG_SECRETS[@]}"; do
    grep -qx "$name" <<<"$visible" || missing+=("$name")
    grep -qx "$name" <<<"$repo_level" && shadowing+=("$name")
  done

  if (( ${#missing[@]} )); then
    SKIPPED+=("secrets da org não visíveis para $REPO: ${missing[*]} (ajuste o acesso do repositório em $ORG_SECRETS_URL)")
    warn "Faltam na org ou não estão liberados para $REPO: ${missing[*]}"
  else
    say "Da org e visíveis para $REPO: ${ORG_SECRETS[*]}"
  fi
  if (( ${#shadowing[@]} )); then
    SKIPPED+=("remover duplicatas locais que sobrescrevem a org: ${shadowing[*]} (gh secret delete NOME)")
    warn "Duplicados no repositório, sobrescrevendo a org: ${shadowing[*]}"
  fi
}

stage_org_secrets() {
  stage "Secrets compartilhados da organização"
  say "AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, AWS_SESSION_TOKEN, AWS_ACCOUNT_ID e DB_PASSWORD"
  say "ficam na org Bunzina. Este wizard só confere; não grava nenhum deles em $REPO."
  say "Para renovar as credenciais do AWS Academy depois: ./scripts/setup-secrets.sh --aws"
  check_org_secrets
  pause
}

stage_aws() {
  stage "AWS Academy: renovar credenciais da organização"
  say "Elas expiram quando o Learner Lab é encerrado e valem para todos os repositórios."
  open_url "https://www.awsacademy.com/vforcesite/LMS_Login"
  step "Entre no curso → Learner Lab → Start Lab e espere o indicador ficar verde."
  step "Clique em 'AWS Details' e, ao lado de 'AWS CLI', em 'Show'."
  note "A interface do Academy muda. Procure o bloco com aws_access_key_id, aws_secret_access_key e aws_session_token."
  open_url "$ORG_SECRETS_URL"
  step "Atualize AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY e AWS_SESSION_TOKEN (Update secret)."
  step "AWS_ACCOUNT_ID só muda se o Learner Lab for outro."
  note "O wizard não grava estes valores: o gh só atualiza secret de org com permissão de admin e redefiniria a visibilidade."
  pause "Atualizou na org?"
  check_org_secrets
}

stage_database() {
  stage "Banco do Billing (Postgres no cluster)"
  say "Usuário com que o chart cria o Postgres do serviço e com que a migration conecta."
  say "A senha é a DB_PASSWORD da org: não é pedida nem gravada aqui."
  warn "Depois do primeiro deploy, trocar a senha não troca a senha dentro do volume do Postgres."
  ask DB_USER "Usuário do banco (ex.: bunzina_billing):"
  require "Usuário do banco" "$DB_USER"
  write_env DB_USER "$DB_USER"
  set_secret DB_USER "$DB_USER"
  note "O .env local fica só como cópia sua. O app não lê DB_USER nem DB_PASSWORD."
}

stage_rabbitmq() {
  stage "RabbitMQ do cluster"
  say "URL AMQP que os pods do Billing usam para falar com o broker."
  step "Em outro terminal: kubectl get svc -A | grep -i rabbit"
  step "Anote o namespace e o nome do serviço. A porta AMQP é 5672."
  step "Pegue o usuário e a senha do broker no Secret do release (ou os que você definiu na instalação)."
  note "O release Helm do RabbitMQ não está nos repositórios que o time versiona localmente, então não sei os nomes exatos."
  say "Formato: amqp://USUARIO:SENHA@SERVICO.NAMESPACE.svc.cluster.local:5672"
  ask_secret RABBITMQ_URL "Cole a RABBITMQ_URL:"
  require "RABBITMQ_URL" "$RABBITMQ_URL"
  set_secret RABBITMQ_URL "$RABBITMQ_URL"
  note "Não vai para o .env: o Bun lê o .env sozinho e apontaria o ambiente local para o broker do cluster."
}

stage_mp_token() {
  stage "Mercado Pago: access token de teste"
  open_url "https://www.mercadopago.com.br/developers/panel/app"
  step "Abra a aplicação de teste → Credenciais de teste."
  step "Copie o Access Token. No ambiente de teste ele começa com TEST-."
  ask_secret MP_ACCESS_TOKEN "Cole o access token:"
  require "access token" "$MP_ACCESS_TOKEN"
  if [[ "$MP_ACCESS_TOKEN" != TEST-* ]]; then
    warn "Esse token não começa com TEST-. Com token de produção as cobranças são reais."
    confirm "Usar mesmo assim?" || exit 1
  fi
  write_env MP_ACCESS_TOKEN "$MP_ACCESS_TOKEN"
  set_secret MP_ACCESS_TOKEN "$MP_ACCESS_TOKEN"
}

stage_mp_webhook() {
  stage "Mercado Pago: assinatura secreta do webhook"
  say "Valida o header x-signature das notificações. O painel só a mostra depois de salvar uma URL de webhook."
  open_url "https://www.mercadopago.com.br/developers/panel/app"
  step "Abra a aplicação → Webhooks → Configurar notificações → modo de teste."
  step "Informe uma URL https provisória (ex.: https://example.com/webhooks/mercadopago)."
  step "Marque o evento Payments e salve."
  step "Revele e copie a assinatura secreta."
  note "Depois do primeiro deploy, volte aqui e troque a URL provisória pela URL pública do Billing."
  note "A interface do painel muda. Se não achar, deixe em branco e preencha depois."
  ask_secret MP_WEBHOOK_SECRET "Cole a assinatura secreta (Enter pula):"
  if [[ -z "$MP_WEBHOOK_SECRET" ]]; then
    SKIPPED+=("MP_WEBHOOK_SECRET (rode o script de novo quando tiver a assinatura)")
    warn "Pulado. Sem ela o webhook não valida a assinatura."
  else
    write_env MP_WEBHOOK_SECRET "$MP_WEBHOOK_SECRET"
    set_secret MP_WEBHOOK_SECRET "$MP_WEBHOOK_SECRET"
  fi
}

stage_smtp() {
  stage "E-mail (SMTP)"
  say "O Billing envia o orçamento e o link de pagamento por SMTP."
  say "Usa os mesmos nomes de variável do monólito: EMAIL_SMTP_* e EMAIL."
  note "O deploy do monólito não define essas variáveis, então não há credencial de produção para reaproveitar."
  note "Para a demo, uma caixa de teste (ex.: Mailtrap → Email Testing → Inboxes → SMTP Settings) evita e-mail real."
  open_url "https://mailtrap.io/inboxes"
  ask EMAIL_SMTP_HOST "Host SMTP:"
  ask EMAIL_SMTP_PORT "Porta SMTP:"
  ask EMAIL_SMTP_USER "Usuário SMTP:"
  ask_secret EMAIL_SMTP_PASSWORD "Senha SMTP:"
  ask EMAIL "Remetente padrão (ex.: bunzina@bunzina.com):"
  require "Host SMTP" "$EMAIL_SMTP_HOST"
  require "Porta SMTP" "$EMAIL_SMTP_PORT"
  require "Remetente" "$EMAIL"
  write_env EMAIL_SMTP_HOST "$EMAIL_SMTP_HOST"
  write_env EMAIL_SMTP_PORT "$EMAIL_SMTP_PORT"
  write_env EMAIL_SMTP_USER "$EMAIL_SMTP_USER"
  write_env EMAIL_SMTP_PASSWORD "$EMAIL_SMTP_PASSWORD"
  write_env EMAIL "$EMAIL"
  set_secret EMAIL_SMTP_HOST "$EMAIL_SMTP_HOST"
  set_secret EMAIL_SMTP_PORT "$EMAIL_SMTP_PORT"
  set_secret EMAIL_SMTP_USER "$EMAIL_SMTP_USER"
  set_secret EMAIL_SMTP_PASSWORD "$EMAIL_SMTP_PASSWORD"
  set_secret EMAIL "$EMAIL"
}

stage_sonar() {
  stage "SonarCloud: projeto e token"
  open_url "https://sonarcloud.io/projects/create"
  step "Organização bunzina → Analyze new project → escolha Bunzina/bunzina-billing."
  step "Se perguntar o método de análise, escolha 'With GitHub Actions'. Senão, desligue a Automatic Analysis em Administration → Analysis Method."
  step "Confirme que a Project Key é Bunzina_bunzina-billing, igual ao sonar-project.properties."
  open_url "https://sonarcloud.io/account/security"
  step "Em Generate Tokens, dê o nome bunzina-billing-ci, gere e copie o token."
  ask_secret SONAR_TOKEN "Cole o token do SonarCloud:"
  require "token do SonarCloud" "$SONAR_TOKEN"
  set_secret SONAR_TOKEN "$SONAR_TOKEN"
}

stage_branch_protection() {
  stage "Proteção da main: quality gate obrigatório"
  say "Hoje a main exige lint-format/check e test/coverage."
  say "Esta etapa acrescenta sonar/quality-gate aos checks obrigatórios de $REPO."
  note "Com o token configurado, o gate passa a reprovar PR que não cumpra o quality gate do Sonar."
  if confirm "Adicionar sonar/quality-gate aos checks obrigatórios da main?"; then
    if gh api -X POST "repos/$REPO/branches/main/protection/required_status_checks/contexts" \
      -f 'contexts[]=sonar/quality-gate' >/dev/null 2>&1; then
      printf '  %s✓ adicionado%s sonar/quality-gate\n' "$GREEN" "$RESET"
    else
      SKIPPED+=("check obrigatório sonar/quality-gate (precisa de permissão de admin; adicione em Settings → Branches)")
      warn "Não consegui alterar a proteção da branch."
    fi
  else
    SKIPPED+=("check obrigatório sonar/quality-gate na main")
  fi
}

if [[ "${1:-}" == "--aws" ]]; then
  TOTAL_STAGES=2
  banner "Billing: renovar credenciais da AWS (org)"
  stage_preflight
  stage_aws
  finish
  return 0
fi

TOTAL_STAGES=9

banner "Billing: secrets e configuração do repositório"

stage_preflight
stage_org_secrets
stage_database
stage_rabbitmq
stage_mp_token
stage_mp_webhook
stage_smtp
stage_sonar
stage_branch_protection

finish
}

run_wizard "$@"; exit
